# --- SHUTDOWN HANDLING ---
shutdown_flag = False
def handle_shutdown_signal(signum, frame):
    global shutdown_flag
    if not shutdown_flag:
        print("\n[Listener] Shutdown signal received. Finishing current cycle and terminating workers...")
        shutdown_flag = True

# --- PROCESS MANAGEMENT ---
def is_process_running(pid: int) -> bool:
    """Checks if a process with the given PID is currently running."""
    if pid is None or pid <= 0:
        return False
    try:
        return psutil.pid_exists(pid)
    except Exception:
        return False

def start_worker_process(instance_id: str, script_path: str):
    """Starts a new worker process for a given instance ID and script."""
    print(f"[Listener] Attempting to start worker for instance {instance_id} using {os.path.basename(script_path)}...")
    try:
        # Note: We assume the user has renamed .py.txt to .py as per instructions
        subprocess.Popen([sys.executable, script_path, instance_id],
                         stdout=sys.stdout,
                         stderr=sys.stderr)
        print(f"[Listener] Worker process for {instance_id} has been launched.")
    except Exception as e:
        print(f"[Listener] ❌ FAILED to launch worker for {instance_id}: {e}")
        try:
            supabase.table("whatsapp_instances").update({
                "status": "failed", "is_active": False, "last_error": f"Orchestrator failed to start process: {e}"
            }).eq("id", instance_id).execute()
        except APIError as db_err:
            print(f"[Listener] ❌ Also failed to update DB on worker start failure: {db_err}")


def stop_worker_process(pid: int):
    """
    Stops a worker process using a two-phase termination:
    1. Sends SIGTERM for a graceful shutdown.
    2. If the process doesn't exit, sends SIGKILL to force termination.
    """
    if not is_process_running(pid):
        print(f"[Listener] Instructed to stop PID {pid}, but it's not running.")
        return

    try:
        proc = psutil.Process(pid)

        # Phase 1: Graceful Shutdown
        print(f"[Listener] Sending SIGTERM to worker with PID {pid} for graceful shutdown...")
        proc.terminate() # proc.terminate() sends SIGTERM on Unix

        # Wait for the process to exit with a timeout
        try:
            proc.wait(timeout=10) # Grace period of 10 seconds
            print(f"[Listener] Worker PID {pid} terminated gracefully.")
        except psutil.TimeoutExpired:
            # Phase 2: Forceful Termination
            print(f"[Listener] ⚠️ Worker PID {pid} did not terminate gracefully. Sending SIGKILL...")
            proc.kill() # proc.kill() sends SIGKILL on Unix
            proc.wait() # Ensure it's gone
            print(f"[Listener] Worker PID {pid} forcefully terminated.")

    except psutil.NoSuchProcess:
        print(f"[Listener] Process {pid} disappeared before it could be managed.")
    except Exception as e:
        print(f"[Listener] ❌ Error stopping PID {pid}: {e}")

# --- MAIN ORCHESTRATION LOGIC ---
def reconcile_workers():
    """The core loop that syncs DB state with running processes."""
    print("\n--- [Listener] Starting Reconciliation Cycle ---")

    # --- 1. WHATSAPP ZOMBIE DETECTION & CLEANUP ---
    try:
        zombie_response = supabase.rpc("get_zombie_instances", {
            "p_hostname": LISTENER_HOSTNAME,
            "p_threshold_seconds": HEARTBEAT_THRESHOLD
        }).execute()
        zombies = zombie_response.data
        if zombies:
            print(f"[Listener] Found {len(zombies)} zombie WhatsApp worker(s) on this host.")
            for zombie in zombies:
                if shutdown_flag: break
                stop_worker_process(zombie['worker_pid'])
                supabase.table("whatsapp_instances").update({
                    "status": "failed", "last_error": "Worker terminated due to missed heartbeat (zombie).",
                    "worker_pid": None, "worker_hostname": None, "last_heartbeat": None
                }).eq("id", zombie['id']).execute()
    except APIError as e:
        print(f"[Listener] ❌ DB_ERROR: Could not perform WhatsApp zombie check: {e}.")

    if shutdown_flag:
        print("--- [Listener] Reconciliation interrupted by shutdown signal ---")
        return

    # --- 2. WHATSAPP STATE RECONCILIATION ---
    try:
        response = supabase.table("whatsapp_instances").select("*").execute()
        print(f"[Listener] Reconciling state for {len(response.data)} WhatsApp instances...")
        for instance in response.data:
            if shutdown_flag: break
            # If instance is 'active' but has no worker, start one.
            if instance['is_active'] and not instance.get('worker_pid'):
                start_worker_process(instance['id'], AIWA_SCRIPT)
            # If instance is NOT active but has a worker running on this host, stop it.
            elif not instance['is_active'] and instance.get('worker_pid') and instance.get('worker_hostname') == LISTENER_HOSTNAME:
                stop_worker_process(instance['worker_pid'])
    except APIError as e:
        print(f"[Listener] ❌ DB_ERROR: Could not fetch WhatsApp instances for reconciliation: {e}.")

    print("--- [Listener] Reconciliation Cycle Complete ---")

# --- MAIN EXECUTION ---
if __name__ == "__main__":
    signal.signal(signal.SIGINT, handle_shutdown_signal)
    signal.signal(signal.SIGTERM, handle_shutdown_signal)

    if not supabase:
        sys.exit(1)

    print("[Listener] Orchestrator started. Entering main reconciliation loop...")
    while not shutdown_flag:
        reconcile_workers()
        print(f"[Listener] Sleeping for {RECONCILE_INTERVAL} seconds...")
        for _ in range(RECONCILE_INTERVAL):
            if shutdown_flag:
                break
            time.sleep(1)

    print("[Listener] Shutdown initiated. Cleaning up all managed workers on this host...")
    try:
        # Cleanup WhatsApp workers
        response_wa = supabase.table("whatsapp_instances").select("id, worker_pid").eq("worker_hostname", LISTENER_HOSTNAME).execute()
        for instance in response_wa.data:
            if instance.get('worker_pid'):
                stop_worker_process(instance['worker_pid'])
    except APIError as e:
        print(f"[Listener] ❌ Could not fetch instances for final cleanup: {e}")

    print("[Listener] Orchestrator has shut down.")

